    'git log*': 'allow',
    'git show*': 'allow',
    'git status*': 'allow',
    'git branch': 'allow',
    'git branch -v': 'allow',
    'grep*': 'allow',
    'head*': 'allow',
    'less*': 'allow',
    'ls*': 'allow',
    'more*': 'allow',
    'pwd*': 'allow',
    'rg*': 'allow',
    'sort --output=*': 'ask',
    'sort -o *': 'ask',
    'sort*': 'allow',
    'stat*': 'allow',
    'tail*': 'allow',
    'tree -o *': 'ask',
    'tree*': 'allow',
    'uniq*': 'allow',
    'wc*': 'allow',
    'whereis*': 'allow',
    'which*': 'allow',
    '*': 'ask',
  },
  webfetch: 'allow',
} as const;

export const ArchitectPlanning: Plugin = async () => {
  return {
    async config(config) {
      config.agent = {
        challenger: {
          name: 'challenger',
